// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);
	imageMode(CENTER)
}
var fires = []
function preload(){
	vol2=loadImage("https://openprocessing.org/sketch/931739/files/vol2.jpeg")
}
function draw() {
	background(255)
	image(vol2,width/2,height/2+80)	
	noStroke();
	for(let i = 0; i < 15; i++){
		fires.push(new fire (width/2,height/2))
	}

	for(let i=0;i<fires.length;i++){
	 fires[i].render(i);
	}
}

function fire(x, y){
	this.x = x;
	this.y = y;
	this.yVel = -random(2+3,7+10);
	this.xVel = random(-this.yVel/3,this.yVel/3);
	this.heat = 201
	this.render = function(num){
		this.x+=this.xVel
		this.y+=this.yVel
		this.yVel+=0.5
		fill(255,0,0,this.heat)
		ellipse(this.x,this.y,10)
		this.heat-=7
		if(this.heat<0){fires.splice(num,1)}
	}	
}

